// Proto
execution.proto RunAgentResponse { ... string park_reason = 11; }
orchestration.proto oneof { RunParked run_parked = 24; RunResumed run_resumed = 25; }
message RunParked { string run_id = 1; string reason = 2; optional uint64 retry_after_ms = 3; string resets_at = 4; }
message RunResumed { string run_id = 1; uint32 resumed_segment = 2; string park_reason = 3; }
sessions.proto SaveLoopCheckpointResponse { uint64 seq = 1; bool park_accepted = 2; }

// HTTP / SSE
POST /api/v1/orchestration/runs/{run_id}/continue
  SPA->BFF {"claim_token"}
  BFF->gateway {"approval_id":"","claim_token"}
frame run_parked {run_id, reason, retry_after_ms?, resets_at?}
orchestration SSE run_resumed {run_id, resumed_segment, park_reason}
park continue failures: a typed error frame (closed token, no approval_spent); the run stays parked
  tokens: park_not_due, park_route_unavailable, park_not_restorable, resume_incomplete, resume_forbidden, continue_in_progress, not_resumable, continue_disabled, continue_refused, continue_unreachable, continue_outcome_unknown
  never agent_dispatch_rejected or agent_dispatch_unreachable

